// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, address(this).balance > 0 ? address(this).balance : 1 ether);
        // fund the test contract so it can deposit into c via the fallback
        vm.deal(address(this), amount);
        // deposit `amount` into c (fallback is payable and counts deposits)
        (bool okDep,) = address(c).call{value: amount}("");
        assertTrue(okDep);
        assertEq(address(c).balance, amount);

        // owner withdraws exactly `amount`; the full amount must leave the contract
        vm.prank(address(this));
        c.withdraw(amount);

        // UNIVERSAL RULE: after owner withdraw(amount), the contract retains NOTHING
        assertEq(address(c).balance, 0, "withdraw(amount) must transfer the full amount out");
    }

    receive() external payable {}
}
